            .unwrap_or_else(|| String::from(BAT_THEME_DEFAULT)),
        line_ranges: LineRanges::from(
            transpose(
                self.matches
                    .values_of("line-range")
                    .map(|vs| vs.map(LineRange::from).collect()),
            )?
            .unwrap_or_else(|| vec![]),
        ),
        output_components,
        syntax_mapping,
        pager: self.matches.value_of("pager"),
        use_italic_text: match self.matches.value_of("italic-text") {
            Some("always") => true,
            _ => false,
        },
        highlight_lines: self
            .matches
            .values_of("highlight-line")
            .and_then(|ws| ws.map(|w| w.parse().ok()).collect())
            .unwrap_or_default(),
    })
}

fn print_line(
    &mut self,
    out_of_range: bool,
    handle: &mut Write,
    line_number: usize,
    line_buffer: &[u8],
) -> Result<()> {
    let mut line = match self.content_type {
        ContentType::BINARY => {
            return Ok(());
        }
        ContentType::UTF_16LE => UTF_16LE
            .decode(&line_buffer, DecoderTrap::Replace)
            .map_err(|_| "Invalid UTF-16LE")?,
        ContentType::UTF_16BE => UTF_16BE
            .decode(&line_buffer, DecoderTrap::Replace)
            .map_err(|_| "Invalid UTF-16BE")?,
        _ => String::from_utf8_lossy(&line_buffer).to_string(),
    };

    if self.config.show_nonprintable {
        line = replace_nonprintable(&line, self.config.tab_width);
    }

    let regions = {
        let highlighter = match self.highlighter {
            Some(ref mut highlighter) => highlighter,
            _ => {
                return Ok(());
            }
        };
        highlighter.highlight(line.as_ref(), self.syntax_set)
    };

    if out_of_range {
        return Ok(());
    }

    let mut cursor: usize = 0;
    let mut cursor_max: usize = self.config.term_width;
    let mut cursor_total: usize = 0;
    let mut panel_wrap: Option<String> = None;

    // Line highlighting
    let highlight_this_line = self
        .config
        .highlight_lines
        .iter()
        .any(|&l| l == line_number);

    let background_color = self
        .background_color_highlight
        .filter(|_| highlight_this_line);

    // Line decorations.
    if self.panel_width > 0 {
        let decorations = self
            .decorations
            .iter()
            .map(|ref d| d.generate(line_number, false, self))
            .collect::<Vec<_>>();

        for deco in decorations {
            write!(handle, "{} ", deco.text)?;
            cursor_max -= deco.width + 1;
        }
    }

const DEFAULT_GUTTER_COLOR: u8 = 238;

#[derive(Default)]
pub struct Colors {
    pub grid: Style,
    pub filename: Style,
    pub git_added: Style,
    pub git_removed: Style,
    pub git_modified: Style,
    pub line_number: Style,
}

impl Colors {
    fn plain() -> Self {
        Colors::default()
    }

    fn colored(theme: &Theme, true_color: bool) -> Self {
        let gutter_color = theme
            .settings
            .gutter_foreground
            .map(|c| to_ansi_color(c, true_color))
            .unwrap_or(Fixed(DEFAULT_GUTTER_COLOR));

        Colors {
            grid: gutter_color.normal(),
            filename: Style::new().bold(),
            git_added: Green.normal(),
            git_removed: Red.normal(),
            git_modified: Yellow.normal(),
            line_number: gutter_color.normal(),
        }
    }
}
